"""Generate GLCE fixed-width font atlas C assets from Spleen BDF files.

Purpose:
    Convert printable ASCII glyphs (0x20-0x7E) in fixed-width BDF fonts
    into a packed, 1-bit-per-pixel font atlas and C metadata.

    The generated assets require no BDF parser, image loader, or CPU
    pixel allocation for the font atlas at GLCE runtime.

    Each byte stores eight horizontally consecutive logical pixels.
    GLCE uploads the packed data directly to an R8UI texture without
    expanding it to RGBA8. During rendering, the fragment shader
    extracts individual bits to reconstruct the glyphs.

Usage (from the repository root):
    python3 tools/bdf_font_atlas_generator/generate.py \\
        assets/fonts/spleen/spleen-12x24.bdf

    # Generate all sizes (the shell expands the wildcard):
    python3 tools/bdf_font_atlas_generator/generate.py \\
        assets/fonts/spleen/*.bdf

Output (relative to glce/):
    engine/systems/renderer/resources/fonts/generated/<font_name>.h
    engine/systems/renderer/resources/fonts/generated/<font_name>.c

The generated .h/.c files refer to the existing font_atlas_asset_t defined
in engine/systems/renderer/resources/fonts/font_atlas_asset.h.  They do not
create or modify that shared header.

Only fixed-width BDF fonts containing all printable ASCII glyphs
(0x20-0x7E) are accepted. The input BDF may contain additional glyphs.

The generator extracts the 95 required glyphs and arranges them
in ASCII code order into 16 columns and 6 rows. The BDF
FONTBOUNDINGBOX defines the dimensions of each glyph cell.

The generated atlas uses 1-bit-per-pixel encoding, MSB-first bits,
row-major storage, byte-padded rows, and a top-left origin.

See README.md for the supported BDF contract, atlas layout,
dimension calculations, and packed pixel data representation.

The generated .c contains font-derived glyph data.  Its SPDX identifier
is BSD-2-Clause, matching Spleen; do not use this generator with another
font until its generated-file license declaration has been reviewed.
"""

from __future__ import annotations

import argparse
from dataclasses import dataclass
from pathlib import Path
import re
import sys


REPOSITORY_GLCE_ROOT = Path(__file__).resolve().parents[2] / "glce"
OUTPUT_DIRECTORY = Path("engine/systems/renderer/resources/fonts/generated")
ASSET_HEADER = Path("engine/systems/renderer/resources/fonts/font_atlas_asset.h")
FIRST_CHARACTER = 32
LAST_CHARACTER = 126
ATLAS_COLUMNS = 16
MAX_ATLAS_PIXELS = 16 * 1024 * 1024


class BdfError(ValueError):
    """Raised when source BDF data violates the supported font contract."""


@dataclass(frozen=True)
class BoundingBox:
    width: int
    height: int
    x_offset: int
    y_offset: int


@dataclass(frozen=True)
class Glyph:
    codepoint: int
    name: str
    box: BoundingBox
    advance_x: int
    bitmap_rows: tuple[int, ...]


@dataclass(frozen=True)
class BdfFont:
    cell: BoundingBox
    glyphs: dict[int, Glyph]
    copyright_notice: str | None


@dataclass(frozen=True)
class Atlas:
    width: int
    height: int
    cell_width: int
    cell_height: int
    advance_x: int
    line_height: int
    pixels: bytes


def parse_integers(text: str, expected: int, where: str) -> tuple[int, ...]:
    fields = text.split()
    if len(fields) != expected:
        raise BdfError(f"{where}: expected {expected} integers, got {text!r}")
    try:
        return tuple(int(field, 10) for field in fields)
    except ValueError as exc:
        raise BdfError(f"{where}: invalid integer: {text!r}") from exc


def parse_box(text: str, where: str) -> BoundingBox:
    width, height, x_offset, y_offset = parse_integers(text, 4, where)
    if width < 0 or height < 0:
        raise BdfError(f"{where}: negative glyph dimensions")
    return BoundingBox(width, height, x_offset, y_offset)


def parse_glyph(lines: list[str], start: int) -> tuple[Glyph | None, int]:
    name = lines[start].partition(" ")[2].strip()
    if not name:
        raise BdfError(f"line {start + 1}: STARTCHAR requires a name")

    encoding: int | None = None
    advance: tuple[int, int] | None = None
    box: BoundingBox | None = None
    bitmap_rows: list[int] | None = None
    i = start + 1
    while i < len(lines):
        line = lines[i].strip()
        i += 1
        if line == "ENDCHAR":
            if encoding is None or advance is None or box is None or bitmap_rows is None:
                raise BdfError(f"glyph {name!r}: missing ENCODING, DWIDTH, BBX, or BITMAP")
            if len(bitmap_rows) != box.height:
                raise BdfError(
                    f"glyph {name!r}: BITMAP has {len(bitmap_rows)} rows, "
                    f"BBX requires {box.height}"
                )
            if encoding < 0:
                return None, i
            if advance[1] != 0:
                raise BdfError(f"glyph {name!r}: vertical DWIDTH is unsupported")
            return Glyph(encoding, name, box, advance[0], tuple(bitmap_rows)), i

        if bitmap_rows is not None:
            row_bytes = (box.width + 7) // 8 if box is not None else 0
            if not re.fullmatch(r"[0-9A-Fa-f]*", line) or len(line) != row_bytes * 2:
                raise BdfError(f"glyph {name!r}, line {i}: invalid BITMAP hex row {line!r}")
            row = int(line, 16) if line else 0
            padding = row_bytes * 8 - box.width
            if padding and (row & ((1 << padding) - 1)):
                raise BdfError(f"glyph {name!r}, line {i}: nonzero row padding bits")
            bitmap_rows.append(row)
            continue

        key, _, value = line.partition(" ")
        if key == "ENCODING":
            # BDF allows ENCODING -1 <alternate>; only primary encodings are used.
            parts = value.split()
            if len(parts) not in (1, 2):
                raise BdfError(f"glyph {name!r}: invalid ENCODING")
            encoding = parse_integers(parts[0], 1, "ENCODING")[0]
        elif key == "DWIDTH":
            advance = parse_integers(value, 2, "DWIDTH")
        elif key == "BBX":
            box = parse_box(value, "BBX")
        elif key == "BITMAP":
            if box is None:
                raise BdfError(f"glyph {name!r}: BBX must precede BITMAP")
            bitmap_rows = []
        elif key == "STARTCHAR":
            raise BdfError(f"glyph {name!r}: nested STARTCHAR")

    raise BdfError(f"glyph {name!r}: missing ENDCHAR")


def parse_bdf(path: Path) -> BdfFont:
    try:
        lines = path.read_text(encoding="utf-8-sig").splitlines()
    except (OSError, UnicodeError) as exc:
        raise BdfError(f"cannot read BDF file {path}: {exc}") from exc
    if not lines or not lines[0].startswith("STARTFONT "):
        raise BdfError(f"{path}: missing STARTFONT")

    font_box: BoundingBox | None = None
    glyphs: dict[int, Glyph] = {}
    notice: str | None = None
    declared_glyphs: int | None = None
    glyph_count = 0
    endfont_seen = False

    i = 1
    while i < len(lines):
        line = lines[i].strip()
        if line.startswith("STARTCHAR "):
            glyph, next_index = parse_glyph(lines, i)
            glyph_count += 1
            if glyph is not None and FIRST_CHARACTER <= glyph.codepoint <= LAST_CHARACTER:
                if glyph.codepoint in glyphs:
                    raise BdfError(f"{path}: duplicate ASCII ENCODING {glyph.codepoint}")
                glyphs[glyph.codepoint] = glyph
            i = next_index
            continue
        i += 1
        key, _, value = line.partition(" ")
        if key == "FONTBOUNDINGBOX":
            font_box = parse_box(value, "FONTBOUNDINGBOX")
        elif key == "COPYRIGHT":
            notice = value.strip().strip('"')
        elif key == "COMMENT" and notice is None and "Copyright" in value:
            notice = value.strip().lstrip("* ").strip()
        elif key == "CHARS":
            declared_glyphs = parse_integers(value, 1, "CHARS")[0]
        elif key == "ENDFONT":
            endfont_seen = True
            if any(trailing.strip() for trailing in lines[i:]):
                raise BdfError(f"{path}: content after ENDFONT")
            break

    if not endfont_seen:
        raise BdfError(f"{path}: missing ENDFONT")
    if font_box is None or font_box.width <= 0 or font_box.height <= 0:
        raise BdfError(f"{path}: invalid or missing FONTBOUNDINGBOX")
    if declared_glyphs is not None and declared_glyphs != glyph_count:
        raise BdfError(f"{path}: CHARS={declared_glyphs}, found {glyph_count} glyphs")

    missing = [value for value in range(FIRST_CHARACTER, LAST_CHARACTER + 1)
               if value not in glyphs]
    if missing:
        preview = ", ".join(str(value) for value in missing[:12])
        raise BdfError(f"{path}: missing ASCII glyphs: {preview}"
                       + (" ..." if len(missing) > 12 else ""))

    return BdfFont(font_box, glyphs, notice)


def build_atlas(font: BdfFont) -> Atlas:
    cell = font.cell
    glyph_count = LAST_CHARACTER - FIRST_CHARACTER + 1
    atlas_rows = (glyph_count + ATLAS_COLUMNS - 1) // ATLAS_COLUMNS
    width = cell.width * ATLAS_COLUMNS
    height = cell.height * atlas_rows
    if width * height > MAX_ATLAS_PIXELS:
        raise BdfError(f"atlas is too large: {width}x{height}")

    row_stride = (width + 7) // 8
    packed = bytearray(row_stride * height)
    for codepoint in range(FIRST_CHARACTER, LAST_CHARACTER + 1):
        glyph = font.glyphs[codepoint]
        box = glyph.box
        if glyph.advance_x != cell.width:
            raise BdfError(
                f"glyph {glyph.name!r} ({codepoint}): DWIDTH {glyph.advance_x} "
                f"does not match fixed cell width {cell.width}"
            )

        dx = box.x_offset - cell.x_offset
        # BDF y offsets are measured from the baseline, positive upwards.
        # Atlas y coordinates count downwards from the font's top edge.
        dy = cell.y_offset + cell.height - (box.y_offset + box.height)
        if dx < 0 or dy < 0 or dx + box.width > cell.width or dy + box.height > cell.height:
            raise BdfError(
                f"glyph {glyph.name!r} ({codepoint}): BBX does not fit FONTBOUNDINGBOX"
            )

        index = codepoint - FIRST_CHARACTER
        cell_x = (index % ATLAS_COLUMNS) * cell.width
        cell_y = (index // ATLAS_COLUMNS) * cell.height
        row_bit_count = ((box.width + 7) // 8) * 8
        for glyph_y, row_bits in enumerate(glyph.bitmap_rows):
            atlas_y = cell_y + dy + glyph_y
            for glyph_x in range(box.width):
                if row_bits & (1 << (row_bit_count - 1 - glyph_x)):
                    atlas_x = cell_x + dx + glyph_x
                    position = atlas_y * row_stride + atlas_x // 8
                    packed[position] |= 1 << (7 - atlas_x % 8)

    return Atlas(width, height, cell.width, cell.height,
                 cell.width, cell.height, bytes(packed))


def symbol_name(stem: str) -> str:
    value = re.sub(r"[^0-9A-Za-z]+", "_", stem).strip("_").lower()
    if not value or value[0].isdigit():
        raise BdfError(f"source filename cannot form a C identifier: {stem!r}")
    return value


def include_guard(header: Path) -> str:
    # The guard tracks the actual repository-relative path, including filename.
    relative = header.resolve().relative_to(REPOSITORY_GLCE_ROOT)
    suffix = re.sub(r"[^A-Za-z0-9]+", "_", relative.as_posix()).strip("_").upper()
    return f"GLCE_{suffix}"


def c_byte_array(data: bytes) -> str:
    lines = []
    for index in range(0, len(data), 12):
        lines.append("    " + ", ".join(f"0x{byte:02X}" for byte in data[index:index + 12]) + ",")
    return "\n".join(lines)


def output_header(path: Path, symbol: str, atlas: Atlas) -> str:
    guard = include_guard(path)
    return f"""// SPDX-License-Identifier: MIT
// Copyright (c) 2026 chocolate-pie24

/**
 * @file {path.name}
 * @brief 固定幅Font Atlasの生成済みアセット宣言。
 * @details tools/bdf_font_atlas_generator/generate.py により自動生成されたファイル。
 *          手動で編集しないこと。Atlasの寸法: {atlas.width} x {atlas.height}。
 */

#ifndef {guard}
#define {guard}

#ifdef __cplusplus
extern "C" {{
#endif

#include "{ASSET_HEADER.as_posix()}"

/**
 * @brief コンパイル済みのFont Atlas Assetを取得する。
 * @details Metadataと1bit Pixel Dataは生成された.cが所有する静的領域に格納される。
 *          呼び出し側は返却ポインタをBorrowし、解放しない。
 * @return 読み取り専用Font Atlas Assetへの非NULLポインタ。
 * @note 返却先はプログラムの実行期間を通じて有効。
 *       Pixel DataはMSB-first、row-major、1bit/pixel。
 *       各行はbyte境界に揃え、Atlasの原点は左上とする。
 */
const font_atlas_asset_t* {symbol}_asset_get(void);

#ifdef __cplusplus
}}
#endif

#endif // {guard}
"""


def output_source(path: Path, header: Path, symbol: str,
                  atlas: Atlas, source_path: Path, notice: str | None) -> str:
    relative_header = header.resolve().relative_to(REPOSITORY_GLCE_ROOT).as_posix()
    try:
        relative_source = source_path.resolve().relative_to(REPOSITORY_GLCE_ROOT.parent).as_posix()
    except ValueError:
        relative_source = source_path.name
    # Keep untrusted font metadata out of executable C tokens and comments.
    copyright_line = ""
    if notice:
        safe = re.sub(r"[\r\n]+", " ", notice).replace("*/", "* /")
        copyright_line = f"// Original BDF copyright: {safe}\n"
    return f"""// SPDX-License-Identifier: BSD-2-Clause
{copyright_line}// Font bitmap derived from {relative_source}
// Refer to assets/fonts/spleen/LICENSE for the original font license.

/**
 * @file {path.name}
 * @brief 固定幅Font Atlasの生成済みアセット定義。
 * @details tools/bdf_font_atlas_generator/generate.py により自動生成されたファイル。
 *          手動で編集しないこと。Pixel Dataは元のBDFから変換したものである。
 */

#include "{relative_header}"

/** @brief MSB-first・行単位byte alignmentの1bit Font Atlas。 */
static const uint8_t {symbol}_pixels[] = {{
{c_byte_array(atlas.pixels)}
}};

/** @brief コンパイル済み固定幅Font Atlas Assetの実体。 */
static const font_atlas_asset_t {symbol}_asset = {{
    .atlas_width = {atlas.width},
    .atlas_height = {atlas.height},
    .cell_width = {atlas.cell_width},
    .cell_height = {atlas.cell_height},
    .atlas_columns = {ATLAS_COLUMNS},
    .first_character = {FIRST_CHARACTER},
    .last_character = {LAST_CHARACTER},
    .advance_x = {atlas.advance_x},
    .line_height = {atlas.line_height},
    .pixels = {symbol}_pixels,
}};

/**
 * @brief 生成済みFont Atlas Assetへの読み取り専用参照を取得する。
 * @return プログラム終了まで有効な非NULLポインタ。
 */
const font_atlas_asset_t* {symbol}_asset_get(void)
{{
    return &{symbol}_asset;
}}
"""


def resolve_output_dir(path: Path) -> Path:
    resolved = path.resolve() if path.is_absolute() else (REPOSITORY_GLCE_ROOT / path).resolve()
    if not resolved.is_relative_to(REPOSITORY_GLCE_ROOT):
        raise BdfError(f"output directory must be within glce/: {resolved}")
    return resolved


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("bdf_files", metavar="FONT.bdf", type=Path, nargs="+",
                        help="One or more input BDF files (shell wildcards supported)")
    parser.add_argument("--output-dir", type=Path, default=OUTPUT_DIRECTORY,
                        help="Output directory relative to glce/ (default: %(default)s)")
    args = parser.parse_args()

    try:
        destination = resolve_output_dir(args.output_dir)
        names = [symbol_name(path.stem) for path in args.bdf_files]
        if len(set(names)) != len(names):
            raise BdfError("input files would generate duplicate C symbols/filenames")
        # Prepare all assets before writing, to avoid partial output on BDF error.
        prepared = [(path, parse_bdf(path)) for path in args.bdf_files]
        atlases = [(path, font, build_atlas(font)) for path, font in prepared]
        destination.mkdir(parents=True, exist_ok=True)
        for path, font, atlas in atlases:
            symbol = symbol_name(path.stem)
            header = destination / f"{symbol}.h"
            source = destination / f"{symbol}.c"
            header.write_text(output_header(header, symbol, atlas), encoding="utf-8", newline="\n")
            source.write_text(output_source(source, header, symbol, atlas, path,
                                            font.copyright_notice), encoding="utf-8", newline="\n")
            print(f"{path.name} -> {header.relative_to(REPOSITORY_GLCE_ROOT)}, "
                  f"{source.relative_to(REPOSITORY_GLCE_ROOT)} "
                  f"({atlas.width}x{atlas.height}, {len(atlas.pixels)} bytes)")
    except (BdfError, OSError, ValueError) as exc:
        print(f"bdf_font_atlas_generator: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
